# ---------- Chunk 3: match the following (10) + assertion-reason (8) ----------
import random
ROM = ["I", "II", "III", "IV"]
LET = ["A", "B", "C", "D"]
def match(h1, h2, pairs, ans, exp, seed):
    # pairs: list of (list I item, correct list II item); list II order shuffled per question
    rng = random.Random(seed)
    right = [p[1] for p in pairs]
    order = right[:]
    while True:
        rng.shuffle(order)
        if all(order[i] != right[i] for i in range(4)) or seed % 3 == 0:
            break
    key = [order.index(r) for r in right]  # index of correct List II item for A..D
    def fmt(k): return ", ".join(f"{LET[i]}-{ROM[k[i]]}" for i in range(4))
    distract = []
    while len(distract) < 3:
        p = key[:]
        i, j = rng.sample(range(4), 2)
        p[i], p[j] = p[j], p[i]
        if rng.random() < 0.5:
            i, j = rng.sample(range(4), 2)
            p[i], p[j] = p[j], p[i]
        if p != key and p not in distract:
            distract.append(p)
    opts = [fmt(d) for d in distract]
    opts.insert(ans, fmt(key))
    q = ("Match List I with List II:\n"
         f"List I ({h1}): " + "  ".join(f"{LET[i]}. {pairs[i][0]}" for i in range(4)) + "\n"
         f"List II ({h2}): " + "  ".join(f"{ROM[i]}. {order[i]}" for i in range(4)) + "\n"
         "Choose the correct answer:")
    add(q, opts, ans, exp)

